import React from 'react';
import { Link } from 'react-router-dom';
import type { YearPerson } from '../year_types/YearTypes';

export default function YearPersonCard({ person }: { person: YearPerson }) {
  const src = person.image || 'http://localhost:9000/images/default-person.png';
  return (
    <div className="person-card">
      <div className="card-header">
        <div className="person-name">{person.person_name}</div>
      </div>
      <div className="card-image">
        <img src={src} alt={person.person_name} onError={(e)=>{ (e.currentTarget as HTMLImageElement).src = 'http://localhost:9000/images/default-person.png'; }} />
      </div>
      <div className="card-years">Период: <strong>{person.year_from} — {person.year_to}</strong></div>
      <p>{person.description}</p>
      <hr />
      <div className="card-footer">
        <a className="details-btn" href={`/person/${person.id}`}>Подробнее →</a>
      </div>
    </div>
  );
}
